CREATE TABLE IF NOT EXISTS profile (
  id SMALLINT PRIMARY KEY CHECK (id = 1), full_name TEXT NOT NULL, role TEXT NOT NULL, summary TEXT NOT NULL,
  availability TEXT NOT NULL, location TEXT NOT NULL, brand TEXT NOT NULL, eyebrow TEXT NOT NULL,
  about_title TEXT NOT NULL, experience_title TEXT NOT NULL, projects_title TEXT NOT NULL, skills_title TEXT NOT NULL,
  education_title TEXT NOT NULL, contact_title TEXT NOT NULL, contact_cta TEXT NOT NULL, status_label TEXT NOT NULL, online_text TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS navigation (position SMALLINT PRIMARY KEY, label TEXT NOT NULL, href TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS social_link (position SMALLINT PRIMARY KEY, label TEXT NOT NULL UNIQUE, value TEXT NOT NULL, href TEXT NOT NULL, image_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS education (id SMALLINT PRIMARY KEY, period TEXT NOT NULL, institution TEXT NOT NULL, degree TEXT NOT NULL, location TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS experience (id SMALLINT PRIMARY KEY, position SMALLINT NOT NULL UNIQUE, period TEXT NOT NULL, role TEXT NOT NULL, company TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS experience_item (id SMALLINT PRIMARY KEY, experience_id SMALLINT NOT NULL REFERENCES experience(id) ON DELETE CASCADE, position SMALLINT NOT NULL, body TEXT NOT NULL, UNIQUE(experience_id, position));
CREATE TABLE IF NOT EXISTS project (id SMALLINT PRIMARY KEY, position SMALLINT NOT NULL UNIQUE, project_type TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, url TEXT NOT NULL, thumbnail_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_tag (id SMALLINT PRIMARY KEY, project_id SMALLINT NOT NULL REFERENCES project(id) ON DELETE CASCADE, position SMALLINT NOT NULL, value TEXT NOT NULL, UNIQUE(project_id, position));
CREATE TABLE IF NOT EXISTS skill_group (id SMALLINT PRIMARY KEY, position SMALLINT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS skill (id SMALLINT PRIMARY KEY, group_id SMALLINT NOT NULL REFERENCES skill_group(id) ON DELETE CASCADE, position SMALLINT NOT NULL, name TEXT NOT NULL, UNIQUE(group_id, position));

INSERT INTO profile VALUES (1, 'Alvan Marvianto', 'Backend Engineer · Distributed Systems · DevOps', 'Software Engineering undergraduate with hands-on experience in backend development, distributed systems, and cloud-native technologies. Building reliable APIs, event-driven integrations, and infrastructure that ships.', 'Open to backend, platform, and infrastructure opportunities', 'Bandung, Indonesia', 'ALVAN//SYS', 'SYSTEM PROFILE / 2026', 'BUILDING SYSTEMS THAT MOVE DATA, NOT JUST SCREENS.', 'EXECUTION LOG', 'PROJECTS', 'TOOLCHAIN', 'EDUCATION', 'LET''S BUILD THE NEXT SYSTEM.', 'INITIATE CONTACT', 'SYSTEM STATUS', 'ONLINE') ON CONFLICT DO NOTHING;
