INSERT INTO experience_item VALUES (1,1,1,'Designed NestJS REST APIs that integrate data across university information systems.'),(2,1,2,'Refactored database queries with parameterized queries and input validation to mitigate SQL injection risks.'),(3,1,3,'Designed and evaluated event-driven data synchronization using Debezium CDC and message brokers.'),(4,2,1,'Built an enterprise integration management system for applications, contracts, payments, and technology stacks.'),(5,2,2,'Developed interactive integration visualizations and admin dashboards.'),(6,2,3,'Built RESTful services and Redis caching to reduce redundant database queries.'),(7,3,1,'Delivered weekly programming labs to 100+ students per semester across data structures, OOP, OS, web, mobile, testing, and software construction.'),(8,3,2,'Provided personalized debugging support that connects theory with production practice.'),(9,4,1,'Conducted 5G core network monitoring research, benchmarking Istio and Cilium.'),(10,4,2,'Maintained the lab official website and its technical presence.'),(11,5,1,'Guided mentees through NDN, SDN, Docker, and Django.'),(12,5,2,'Led weekly technical discussions and provided final-project feedback.') ON CONFLICT DO NOTHING;
INSERT INTO project VALUES (1,1,'UNDERGRADUATE THESIS','Event-Driven Data Synchronization','One-way CDC synchronization architecture between microservice and legacy systems, evaluating Debezium with Kafka, RabbitMQ, and Redpanda.','https://github.com/alvanmarvianto','https://minio.alvan.my.id/portfolio-assets/projects/event-sync.svg'),(2,2,'RESEARCH','5G Core Network Monitoring','Service-mesh monitoring research for 5G Core environments, benchmarking Istio and Cilium with throughput and latency measurements.','https://github.com/alvanmarvianto','https://minio.alvan.my.id/portfolio-assets/projects/5g-monitoring.svg'),(3,3,'APPLICATION','NewCity','Multi-platform civic reporting system with citizen and government mobile apps plus an administrative web dashboard.','https://github.com/alvanmarvianto','https://minio.alvan.my.id/portfolio-assets/projects/newcity.svg') ON CONFLICT DO NOTHING;
